// utils/datas.js
export const paraISO = (br) => {
  if (!br) return null;
  const [dia, mes, ano] = br.split('/');
  return `${ano}-${mes}-${dia}`; // YYYY-MM-DD
};

export const paraBR = (iso) => {
  if (!iso) return '';
  const [ano, mes, dia] = iso.split('-');
  return `${dia}/${mes}/${ano}`; // DD/MM/YYYY
};
